import corpus from "./corpus.json";
import { createTideweOutdoorProfile, sanitizeCreativeProfile, type TideweOutdoorProfile } from "@/lib/creative-profiles";
import type { ScriptGenerationInput } from "@/lib/script-engine/prompts";
import { normalizeProductFacts, productFactsFromDescription } from "./facts";
import { getTideweShotCount, type ProductFacts } from "./types";
import { tidewePresenterForPrompt } from "./presenter";
import { resolveTideweShopCategory, type TideweShopCategory } from "./categories";
import { buildTideweCategoryGuidance } from "./category-guidance";
import { TIDEWE_NATIVE_CAMERA_STYLE } from "./visual-policy";

const TIDEWE_SHOT_COUNT_RULE = `30s=${getTideweShotCount(30)} shots, 40s=${getTideweShotCount(40)} shots, and 60s=${getTideweShotCount(60)} shots`;

export function tideweProfileForInput(input: ScriptGenerationInput): TideweOutdoorProfile | undefined {
  const profile = sanitizeCreativeProfile(input.creativeProfile);
  if (profile?.creationType === "tidewe_outdoor") return profile;
  if (input.styleType === "tidewe_outdoor") return createTideweOutdoorProfile(input);
  return undefined;
}
export function tideweFactsForInput(input: ScriptGenerationInput): ProductFacts {
  const normalized = normalizeProductFacts(input.productFacts);
  const facts = normalized ?? productFactsFromDescription(input.productDescription, input.productCategoryHint);
  const rawCategory = normalized
    ? input.productFacts && typeof input.productFacts === "object" && !Array.isArray(input.productFacts) ? input.productFacts.category : undefined
    : input.productCategoryHint;
  return { ...facts, category: resolveTideweShopCategory(rawCategory) ?? resolveTideweShopCategory(facts.category) ?? "other" };
}
export function selectTideweExamples(facts: ProductFacts, angle = "auto") {
  const category = resolveTideweShopCategory(facts.category);
  if (!category) return [];
  return corpus.examples.filter(example => CORPUS_PRODUCT_CATEGORIES[example.product] === category).sort((a, b) => {
    const score = (e: typeof a) => (facts.sku?.trim().toUpperCase().startsWith(e.product) ? 4 : 0)
      + (angle === "gift" && [30, 31].includes(e.source.row) ? 3 : 0);
    return score(b) - score(a);
  }).slice(0, 3);
}

// These reviewed products supply examples only for their actual shop category.
const CORPUS_PRODUCT_CATEGORIES: Readonly<Record<string, TideweShopCategory>> = {
  BL022: "hunting_blind", WD012: "waders", JTC001: "heated_gear", HJ006: "heated_gear", THC003: "accessories", THC004: "accessories",
};
const SKU_SAFEGUARDS: Readonly<Record<string, string>> = {
  HJ006: "Half zip; compatible battery sold separately. Never claim a supplied battery or a heated pouch.",
  JTC001: "Water repellent, not waterproof. Omit conflicting runtime claims.",
  THC004: "Heated seat only; do not add back heating.",
  THC003: "Separate seat and back controls; do not substitute another chair's controls.",
  WD012: "Body and boot insulation are separate; never describe insulation grams as whole-item weight.",
  BL022: "The referenced variant has three see-through sides/270 degrees/an upward door; do not substitute BL025's four sides/360 degrees/side door.",
  BL025: "Do not substitute BL022's three sides/270 degrees/upward door for this variant's four sides/360 degrees/side door.",
};

/** Selected-SKU exclusions constrain claims; they never establish current facts. */
export function tideweProductSafeguards(facts: ProductFacts) {
  const sku = facts.sku?.trim().toUpperCase();
  if (!sku) return [];
  return Object.entries(SKU_SAFEGUARDS).filter(([id]) => sku.startsWith(id)).map(([id, restriction]) => ({ sku: id, restriction }));
}

